def pack_context(parts, budget):
    required = [p for p in parts if p["required"]]
    used = sum(p["tokens"] for p in required)
    if used > budget:
        raise ValueError("required parts alone exceed the budget")
    chosen = {p["name"] for p in required}
    for p in sorted((p for p in parts if not p["required"]), key=lambda p: -p["priority"]):
        if used + p["tokens"] <= budget:
            chosen.add(p["name"])
            used += p["tokens"]
    return [p["name"] for p in parts if p["name"] in chosen]

