import json

def get_structured(call_model, validate, prompt, max_tries=3):
    messages = [{"role": "user", "content": prompt}]
    for _ in range(max_tries):
        reply = call_model(messages)
        messages.append({"role": "assistant", "content": reply})
        try:
            obj = json.loads(reply)
        except json.JSONDecodeError as e:
            errors = [f"invalid JSON: {e.msg}"]
        else:
            errors = validate(obj)
            if not errors:
                return obj
        messages.append({"role": "user", "content": "Fix these problems and reply with JSON only: " + "; ".join(errors)})
    raise RuntimeError(f"no valid reply after {max_tries} tries")

