class Transient(Exception):
    retryable = True      # e.g. a timeout or a rate limit

class Fatal(Exception):
    retryable = False     # e.g. an invalid request: retrying cannot help


def retry_call(fn, max_attempts, sleep, rand, base=1.0, cap=30.0):
    for attempt in range(max_attempts):
        try:
            return fn()
        except Exception as e:
            if not getattr(e, "retryable", False) or attempt == max_attempts - 1:
                raise
            sleep(min(cap, base * 2 ** attempt) * rand())
